import test from 'node:test';
import assert from 'node:assert/strict';
import {transformWithOxc} from 'vite';
const data=code=>'data:text/javascript;base64,'+Buffer.from(code).toString('base64');
const lit=data('export const nothing=null;export function html(strings,...values){return {strings,values};}');
const profile=data((await transformWithOxc(await readStagedSource('src/adapters/profile.ts'),'profile.ts')).code);
const controls=data((await transformWithOxc(await readStagedSource('src/ui/adapters.ts'),'adapters.ts')).code);
const {adapterRegistration}=await import(await stagedModuleURL('src/protocol/adapters.ts',{'./json.js':await stagedModuleURL('src/protocol/json.ts'),'../adapters/profile.js':profile}));
let code=(await transformWithOxc(await readStagedSource('src/ui/adapter-library.ts'),'adapter-library.ts')).code;
for(const [name,value] of [['../observability/adapter-upload.js',adapterUploadURL],['lit',lit],['./adapters.js',controls],['./model-owner.js',uiModelOwnerURL],['../observability/model-memory.js',modelMemoryURL],['../adapters/profile.js',profile]])code=code.replaceAll(JSON.stringify(name),JSON.stringify(value)).replaceAll("'"+name+"'",JSON.stringify(value));
const {AdapterLibraryEditing,attachAdapterVersion,adapterScale,adapterStatus,adapterImportProvenance}=await import(data(code));
const hash='sha256:'+'1'.repeat(64),blob={hash,byteLength:'24',mediaType:'application/octet-stream'};
const entry=(changes={})=>({versionId:'version_1',adapterId:'adapter_1',version:'1',name:'Local study',declaredFamily:'ideogram-v4',declaredFormat:'fal',qualification:'structurally-valid',available:true,weights:blob,config:null,profileId:null,runtimeVerified:false,locallyEligible:false,reason:'PROFILE_UNAVAILABLE',...changes});
const eligible=(changes={})=>entry({profileId:'v4-fal-public-example-1',locallyEligible:true,...changes});
const tick=()=>new Promise(r=>setTimeout(r,5));const flush=async()=>{for(let i=0;i<15;i++)await Promise.resolve();};
function find(t,part){if(!t||typeof t!=='object')return;if(t.strings){const i=t.strings.findIndex(s=>s.includes(part));if(i>=0)return {strings:t.strings.slice(i),values:t.values.slice(i)};const attribute=/^(id|label)="([^"]+)"$/.exec(part),bound=attribute===null?-1:t.values.findIndex((value,index)=>value===attribute[2]&&t.strings[index].endsWith(' '+attribute[1]+'='));if(bound>=0)return {strings:t.strings.slice(bound+1),values:t.values.slice(bound+1)};}for(const v of Array.isArray(t)?t:t.values??[]){const r=find(v,part);if(r)return r;}}
function event(properties={}){const host={isConnected:true,...properties};return {currentTarget:host,composedPath:()=>[host],defaultPrevented:false};}
function fixture(initial=[],initialIssues=[]){let selected=initial,issues=initialIssues,rendered,identity='client',controller;const uploads=[],commands=[],reads=[],changes=[],focuses=[];const editor={view:{ready:true,document:{id:'doc',revision:'1'}},sessionId:'session',session:{identity:()=>identity},draftOwner:{drafts:new Map()},async flushDrafts(){},async upload(file,purpose,mediaType){uploads.push({file,purpose,mediaType});return {stagingId:'stage_'+uploads.length,sha256:hash};},async command(command){commands.push(command);return [{type:'AssetRegistered',payload:{asset:{id:'asset_'+commands.length,version:'1',blob,dependencies:[],purpose:'adapter',availability:'available',safety:'unknown',qualification:'pending-adapter'}}}];},async json(path){reads.push(path);return path.startsWith('/api/v1/adapters/')?eligible():{protocolVersion:1,items:[entry()],nextAfter:null};}};const host={querySelector(selector){return {isConnected:true,focus(){focuses.push(selector);}};},requestUpdate(){this.updateComplete=Promise.resolve().then(()=>render());},updateComplete:Promise.resolve()};const change=next=>{changes.push(next);selected=next;issues=[];};function render(){rendered=controller.render(selected,change,issues);return rendered;}ownFixtureJSON(editor);controller=new AdapterLibraryEditing(host,ownFixtureCommands(editor));render();return {controller,editor,host,uploads,commands,reads,changes,focuses,render,template:()=>rendered,identity(v){identity=v;},selected:()=>selected,issues:()=>issues,setIssues(next){issues=next;render();},async choose(kind,file){const part=find(rendered,'label="'+kind+'"');part.values.find(v=>typeof v==='function')(event({files:[file]}));await flush();},async click(id){const part=find(rendered,'id="'+id+'"');assert(part,'rendered '+id);part.values.find(v=>typeof v==='function')(event());await tick();await flush();}};}

test('attachment requires an available supported profile, deduplicates exact versions and caps at three',()=>{
 assert.throws(()=>attachAdapterVersion([],entry()),/cannot attach/);assert.throws(()=>attachAdapterVersion([],eligible({available:false})),/cannot attach/);
 assert.throws(()=>attachAdapterVersion([],eligible({profileId:'unknown-future-profile'})),/cannot attach/);
 const selected=attachAdapterVersion([],eligible());assert.deepEqual(selected,[{version:'version_1',hash,scale:'1'}]);assert.equal(selected[0].runtimeAcknowledged,undefined);
 assert.throws(()=>attachAdapterVersion(selected,eligible()),/already attached/);assert.throws(()=>attachAdapterVersion(['a','b','c'].map(version=>({version,hash,scale:'1'})),eligible()),/at most three/);
});
test('scale retains zero and rejects empty, nonfinite and out-of-range edits',()=>{for(const value of ['0','0.0','1.25','4'])assert.equal(adapterScale(value),value);for(const value of ['',' ','NaN','Infinity','-0.1','4.01'])assert.throws(()=>adapterScale(value),/0 to 4/);});
test('import provenance retains exact local names and rejects combined overflow without truncation',()=>{const files={weights:new File(['x'],'name.safetensors'),config:null,provenance:null};assert.equal(adapterImportProvenance(files,'Source https://example.test'), 'Local filenames: {"weights":"name.safetensors","config":null,"provenance":null}\nUser provenance: Source https://example.test');assert.throws(()=>adapterImportProvenance(files,'x'.repeat(4096)),/exceeds 4096/);});
test('library status distinguishes local structural evidence, runtime evidence and missing artifacts',()=>{assert.equal(adapterStatus(entry()),'Stored — compatibility unverified');assert.equal(adapterStatus(eligible()),'Not runtime verified');assert.equal(adapterStatus(entry({qualification:'incompatible'})),'Incompatible');assert.equal(adapterStatus(entry({available:false})),'Missing artifact');assert.match(adapterStatus(entry({locallyEligible:true,runtimeVerified:true})),/^Runtime verified/);});
test('rendered import stages original handles then requires explicit hash review before registration',async()=>{
 const f=fixture(),weights=new File(['weights'],'study.safetensors'),config=new File(['{}'],'config.json'),provenance=new File(['origin'],'source.txt');
 await f.choose('Adapter weights',weights);await f.choose('Optional adapter config',config);await f.choose('Optional adapter provenance',provenance);await f.click('prepare-adapter-import');
 assert.deepEqual(f.uploads.map(x=>[x.file,x.purpose,x.mediaType]),[[weights,'adapter','application/octet-stream'],[config,'caption','text/plain'],[provenance,'caption','text/plain']]);
 assert.equal(f.commands.length,3);assert(f.commands.every(c=>c.type==='FinalizeStaging'));assert(find(f.template(),'Register immutable adapter version'));
 await f.click('register-adapter-version');assert.deepEqual(f.commands[3],{type:'RegisterAdapterVersion',adapterId:null,previousVersionId:null,weightsAssetId:'asset_1',configAssetId:'asset_2',provenanceAssetId:'asset_3',name:'study',declaredFamily:'ideogram-v4',declaredFormat:'fal',provenanceText:adapterImportProvenance({weights,config,provenance},'')});
 assert.equal(f.reads.at(-1),'/api/v1/adapters');assert(find(f.template(),'Stored versions'));
});
function fieldPart(t,id){if(!t||typeof t!=='object')return;if(t.strings){let i=t.strings.findIndex(s=>s.includes('id="'+id+'"'));if(i<0)i=t.values.findIndex((value,index)=>value===id&&t.strings[index].endsWith('id='));if(i>=0)return {strings:t.strings.slice(i),values:t.values.slice(i)};}for(const v of Array.isArray(t)?t:t.values??[]){const result=fieldPart(v,id);if(result)return result;}}
function fieldProperty(template,id,name){const part=fieldPart(template,id);assert(part,'rendered '+id);const index=part.strings.findIndex(value=>value.endsWith('.'+name+'='));assert(index>=0,'bound '+id+'.'+name);return part.values[index];}
async function editField(f,id,value){const part=fieldPart(f.template(),id);assert(part,'rendered '+id);const input=event({value});part.values.find(v=>typeof v==='function')(input);await flush();return input;}
const validationItems=f=>find(f.template(),'id="adapter-validation-summary"')?.values[0];
