 assert.equal(fieldProperty(f.template(),'adapter-name','value'),'  ');assert.equal(fieldProperty(f.template(),'adapter-family','value'),'x'.repeat(121));assert.equal(fieldProperty(f.template(),'adapter-format','value'),'');assert.equal(fieldProperty(f.template(),'adapter-provenance','value'),'p'.repeat(4096));assert.deepEqual(fieldProperty(f.template(),'adapter-weights','files'),[weights]);
 const prior=f.controller.validation;await editField(f,'adapter-name','Corrected name');assert.notEqual(f.controller.validation,prior);assert.equal(fieldProperty(f.template(),'adapter-name','error'),'');assert.deepEqual(validationItems(f).map(item=>item.target),['adapter-family','adapter-format','adapter-provenance']);assert.equal(f.focuses.length,1);
 await editField(f,'adapter-family','ideogram-v4');await editField(f,'adapter-format','fal');await editField(f,'adapter-provenance','Retained source text');assert.equal(validationItems(f),undefined);assert.equal(fieldProperty(f.template(),'adapter-provenance','error'),'');assert.equal(f.uploads.length,0);await f.click('prepare-adapter-import');assert.equal(f.uploads.length,1);assert.equal(f.uploads[0].file,weights);assert(find(f.template(),'Register immutable adapter version'));
