for(const weights of [null,new File([],'empty.safetensors')])test('missing or empty local weights receive the exact field error without transfer '+(weights?.name??'missing'),async t=>{const f=fixture();t.after(()=>f.controller.dispose());if(weights)await f.choose('Adapter weights',weights);await f.click('prepare-adapter-import');assert.equal(validationItems(f)[0].target,'adapter-weights');assert(fieldProperty(f.template(),'adapter-weights','error'));assert.equal(f.uploads.length,0);assert.equal(f.commands.length,0);});
