for(const boundary of ['document','revision','session','identity','owner','edited','action','disposed','accordion','field','collapsed'])test('pending import summary navigation refuses '+boundary+' changes',async t=>{
 const f=await invalidNameFixture(t);let finish,releasing;const controls=validationFocusControls(f,{settled:new Promise(resolve=>finish=resolve)}),validation=f.controller.validation,pending=f.controller.focusValidation(f.controller.capture(),validation,'adapter-name');await flush();assert.deepEqual(controls.calls,[true]);
 if(boundary==='document')f.editor.view.document={id:'other',revision:'1'};if(boundary==='revision')f.editor.view.document.revision='2';if(boundary==='session')f.editor.sessionId='other';if(boundary==='identity')f.identity('other');if(boundary==='owner')f.editor.draftOwner={drafts:new Map()};if(boundary==='edited')await editField(f,'adapter-name','Corrected');if(boundary==='action'){f.controller.action(event(),f.controller.capture(),()=>{});await tick();await flush();assert.equal(f.controller.busy,false);assert.equal(f.controller.validation,validation);}if(boundary==='disposed')releasing=f.controller.dispose();if(boundary==='accordion')controls.current={...controls.accordion};if(boundary==='field')f.host.querySelector('#adapter-name').isConnected=false;if(boundary==='collapsed')controls.accordion.open=false;
 finish();assert.equal(await pending,false);await releasing;assert.deepEqual(f.focuses,[]);
});
