for(const [id,key,label]of [['adapter-name','name','Adapter name'],['adapter-family','declaredFamily','Declared model family'],['adapter-format','declaredFormat','Declared naming format'],['adapter-provenance','provenanceText','Import provenance']])test('import '+key+' agrees with the real registration protocol control-character boundary',async t=>{
 const f=fixture(),weights=new File(['weights'],'study.safetensors');t.after(()=>f.controller.dispose());await f.choose('Adapter weights',weights);
 const body=value=>({type:'RegisterAdapterVersion',adapterId:null,previousVersionId:null,weightsAssetId:'weights_1',configAssetId:null,provenanceAssetId:null,name:'Study',declaredFamily:'ideogram-v4',declaredFormat:'fal',provenanceText:'Source text',[key]:key==='provenanceText'?adapterImportProvenance({weights,config:null,provenance:null},value):value});
 for(const point of [0,8,11,12,14,31]){const value='before'+String.fromCharCode(point)+'after';assert.throws(()=>adapterRegistration(body(value)),/ADAPTER_RECORD_INVALID/);const input=await editField(f,id,value);await f.click('prepare-adapter-import');assert.equal(input.currentTarget.value,value);assert.equal(fieldProperty(f.template(),id,'value'),value);assert.equal(fieldProperty(f.template(),id,'error'),label+' cannot contain control characters other than tab, line feed or carriage return.');assert.deepEqual(validationItems(f).map(issue=>issue.target),[id]);assert.deepEqual(fieldProperty(f.template(),'adapter-weights','files'),[weights]);assert.equal(f.uploads.length,0);assert.equal(f.commands.length,0);}
 // The protocol permits these three whitespace controls and DEL. Do not widen its rejection set.
 for(const point of [9,10,13,127]){const value='before'+String.fromCharCode(point)+'after';assert.doesNotThrow(()=>adapterRegistration(body(value)));await editField(f,id,value);assert.equal(fieldProperty(f.template(),id,'error'),'');assert.equal(validationItems(f),undefined);assert.deepEqual(f.controller.validationIssues('import'),[]);}
 await editField(f,id,'Corrected value');await f.click('prepare-adapter-import');assert.equal(f.uploads.length,1);assert.equal(f.uploads[0].file,weights);
});
