function scaleFocusControls(f,{allowed=true,settled=Promise.resolve()}={}){
 const original=f.host.querySelector.bind(f.host),calls=[],fields=new Map();const accordion={isConnected:true,open:false,updateComplete:settled,requestOpen(open){calls.push(open);if(allowed)this.open=open;return allowed?'committed':'canceled';}};
 const controls={accordion,current:accordion,calls,fields};f.host.querySelector=selector=>{if(selector==='#request-adapters')return controls.current;if(selector.startsWith('#request-adapter-scale-')){if(!fields.has(selector))fields.set(selector,{isConnected:true,focus(){f.focuses.push(selector);}});return fields.get(selector);}return original(selector);};return controls;
}
