function dynamicId(t,id){if(!t||typeof t!=='object')return;if(t.strings){const i=t.values.indexOf(id);if(i>=0&&t.strings[i].endsWith('id='))return t.values.slice(i).find(v=>typeof v==='function');}for(const v of Array.isArray(t)?t:t.values??[]){const result=dynamicId(v,id);if(result)return result;}}
async function deletionFixture(blocked=false){const f=fixture(),plan={kind:'adapter-deletion-plan-1',id:'plan',versionId:'version_1',adapterId:'adapter_1',version:'1',weights:blob,owner:'client',dependencies:blocked?[{kind:'draft',id:'draft_1',detail:'Request still references this exact version'}]:[],dependencyCount:blocked?1:0,dependenciesTruncated:false,dependencyHash:hash,canDelete:!blocked,actualFreedBytes:'0',bytesRetained:true,token:hash};let deleted=false;f.editor.command=async c=>{f.commands.push(c);if(c.type==='DeleteAdapterVersion')deleted=true;return [{type:'AssetRegistered',payload:{asset:{id:'plan',adapterDeletion:{kind:c.type==='PreviewAdapterDeletion'?'preview':'deleted',versionId:'version_1',planId:'plan',token:hash}}}}];};f.editor.json=async path=>{f.reads.push(path);return path.includes('/deletion-reviews/')?plan:{protocolVersion:1,items:deleted?[]:[entry()],nextAfter:null};};await f.click('search-adapter-library');const callback=dynamicId(f.template(),'preview-adapter-deletion-version_1');assert(callback);callback(event());await tick();await flush();return {f,plan};}
