const attachmentIssue=code=>({field:'adapters',code,message:({ADAPTER_COUNT:'Attach 1–3 eligible versions.',DUPLICATE_ADAPTER:'Duplicate adapter versions are not allowed.',ADAPTER_RUNTIME_ACK_REQUIRED:'Acknowledge runtime uncertainty for the attached adapter versions.'})[code]??'Other issue'});
const restoredAttachments=count=>Array.from({length:count},(_,index)=>({version:'restored_'+index,hash,scale:index===0?'0':String(index%4)}));
function attachmentFocusControls(f,{allowed=true,settled=Promise.resolve()}={}){
 const original=f.host.querySelector.bind(f.host),calls=[],fields=new Map(),accordion={isConnected:true,open:false,updateComplete:settled,requestOpen(open){calls.push(open);if(allowed)this.open=open;return allowed?'committed':'canceled';}},controls={accordion,current:accordion,calls,fields};
 f.host.querySelector=selector=>{if(selector==='#request-adapters')return controls.current;if(selector==='#adapter-search'||selector.startsWith('#request-adapter-remove-')||selector.startsWith('#request-adapter-ack-')){if(!fields.has(selector))fields.set(selector,{isConnected:true,focus(){f.focuses.push(selector);}});return fields.get(selector);}return original(selector);};return controls;
}
