// Exercise the rendered public controls through their actual binding callbacks.
function namedButton(template,label){
 if(!template||typeof template!=='object')return;
 if(template.strings){const at=template.values.findIndex((value,index)=>value===label&&template.strings[index].endsWith('>')&&template.strings[index+1].startsWith('</en-button>'));if(at>=0)return template;}
 for(const child of Array.isArray(template)?template:template.values??[]){const found=namedButton(child,label);if(found)return found;}
}
function buttonDisabled(button){assert(button,'rendered public button');const index=button.strings.findIndex(part=>part.endsWith('?disabled='));assert(index>=0,'actual disabled binding');return button.values[index];}
test('shared action rendering retains exact public IDs, labels, disabled bindings and removal ownership',async t=>{
 const original=[{version:'first',hash,scale:'0',runtimeAcknowledged:true},{version:'second',hash,scale:'4'}],f=fixture(original);t.after(()=>f.controller.dispose());
 for(const [id,label,disabled] of [['prepare-adapter-import','Review local adapter import',true],['search-adapter-library','Search local library',false],['check-adapter-updates','Check attachment updates',false],['request-adapter-remove-1','Remove adapter 2',false]]){
  const part=find(f.template(),'id="'+id+'"');assert(part,id);assert(part.values.includes(label),label);assert.equal(buttonDisabled(part),disabled,id);assert.equal(typeof part.values.find(value=>typeof value==='function'),'function',id);
 }
 assert.equal(find(f.template(),'id="unrelated-adapter-action"'),undefined);
 const remove=find(f.template(),'id="request-adapter-remove-1"').values.find(value=>typeof value==='function'),canceled=event();remove(canceled);canceled.defaultPrevented=true;await tick();await flush();assert.equal(f.selected(),original);assert.equal(f.changes.length,0);
 await f.click('request-adapter-remove-1');assert.deepEqual(f.selected(),[original[0]]);assert.notEqual(f.selected()[0],original[0]);assert.equal(original.length,2);assert.equal(f.commands.length,0);assert.equal(f.uploads.length,0);
 f.identity('replacement');remove(event());await tick();await flush();assert.equal(f.changes.length,1,'old rendered callback cannot change the replacement owner');
});
