 namedButton(f.template(),'Move adapter 2 earlier').values.find(value=>typeof value==='function')(event());await tick();await flush();assert.deepEqual(f.selected(),snapshot);assert.equal(f.selected()[0].scale,'0');assert.equal(f.selected()[0].runtimeAcknowledged,true);
 const retained=f.selected();earlier.values.find(value=>typeof value==='function')(event());await tick();await flush();assert.equal(f.selected(),retained,'stale rendered selection cannot reorder the replacement list');assert.equal(f.commands.length,0);assert.equal(f.uploads.length,0);
